#!/bin/bash
# list.sh [--room ROOM] [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
set -u
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
usage() { echo "usage: list.sh [--room ROOM] [DATE]" >&2; exit 2; }
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
room=
if [ "${1:-}" = --room ]; then [ $# -ge 2 ] || usage; room=$2; shift 2; fi
d=${1:-}
if [ -n "$d" ]; then
  m=${d:5:2}; day=${d:8:2}
  if ! [[ $d =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || [ $((10#$m)) -lt 1 ] || [ $((10#$m)) -gt 12 ] || [ $((10#$day)) -lt 1 ] || [ $((10#$day)) -gt 31 ]; then
    echo "bad date: $d (expected YYYY-MM-DD)" >&2; exit 2
  fi
fi
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="$d" -v r="$room" 'NF && (d == "" || $2 == d) && (r == "" || $1 == r) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort

